// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"runtime/debug"
	"slices"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown or Stop has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout bounds how long Stop waits for running jobs.
const stopTimeout = 30 * time.Second

// entry is a job with its position in the enqueue order.
type entry struct {
	seq uint64
	job Job
}

// active is a job that is running right now.
type active struct {
	cancel   context.CancelFunc
	canceled bool // set by Shutdown when it cancels the job; guarded by Runner.mu
}

// Runner runs jobs on its workers.
type Runner struct {
	queue   chan entry
	workers int
	log     *slog.Logger
	wg      sync.WaitGroup // one count per worker goroutine

	mu       sync.Mutex
	seq      uint64             // sequence number for the next enqueued job
	closing  bool               // set by the first Shutdown; no job starts after it
	waiting  []entry            // enqueued jobs no worker has taken yet, in enqueue order
	running  map[uint64]*active // jobs being run, by sequence number
	notStart []entry            // jobs that were waiting when Shutdown began
	canceled []entry            // jobs Shutdown canceled that then returned an error
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	return &Runner{
		queue:   make(chan entry, queueSize),
		workers: workers,
		log:     log,
		running: make(map[uint64]*active),
	}
}

// Start starts the workers. It does nothing after Shutdown.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closing {
		return
	}
	for i := 0; i < r.workers; i++ {
		r.wg.Add(1)
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	// The queue is closed by Shutdown, so this loop ends once the workers have
	// taken every entry left in it.
	for e := range r.queue {
		r.run(e)
	}
}

// run runs one job unless Shutdown has begun, in which case the job stays in notStart.
func (r *Runner) run(e entry) {
	r.mu.Lock()
	if r.closing {
		r.mu.Unlock()
		return
	}
	r.removeWaiting(e.seq)
	ctx, cancel := context.WithCancel(context.Background())
	a := &active{cancel: cancel}
	r.running[e.seq] = a
	r.mu.Unlock()

	err := r.call(ctx, e.job)
	cancel()

	r.mu.Lock()
	delete(r.running, e.seq)
	if err != nil && a.canceled {
		r.canceled = append(r.canceled, e)
	}
	r.mu.Unlock()
	if err != nil {
		r.log.Error("job failed", "job", e.job.Name, "err", err)
	}
}

// call runs j and recovers a panic, which is logged and reported as no error so the job is not retried.
func (r *Runner) call(ctx context.Context, j Job) (err error) {
	defer func() {
		if v := recover(); v != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", v, "stack", string(debug.Stack()))
			err = nil
		}
	}()
	return j.Run(ctx)
}

// removeWaiting drops the entry with sequence number seq from waiting. The caller holds mu.
func (r *Runner) removeWaiting(seq uint64) {
	for i, e := range r.waiting {
		if e.seq == seq {
			r.waiting = slices.Delete(r.waiting, i, i+1)
			return
		}
	}
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closing {
		return ErrStopped
	}
	e := entry{seq: r.seq, job: j}
	select {
	case r.queue <- e:
	default:
		return ErrQueueFull
	}
	r.seq++
	r.waiting = append(r.waiting, e)
	return nil
}

// Shutdown stops the runner. Enqueue returns ErrStopped from the moment Shutdown is called, and jobs that have
// not started are not started. Shutdown waits for the running jobs to finish. If ctx ends first, it cancels the
// context of every running job, waits for them to return, and returns ctx.Err(). It returns nil when every
// running job finished before ctx ended. Calls after the first return nil at once.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closing {
		r.mu.Unlock()
		return nil
	}
	r.closing = true
	r.notStart = r.waiting
	r.waiting = nil
	close(r.queue)
	r.mu.Unlock()

	done := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(done)
	}()
	select {
	case <-done:
		return nil
	case <-ctx.Done():
	}
	select {
	case <-done:
		return nil
	default:
	}

	r.mu.Lock()
	for _, a := range r.running {
		a.canceled = true
		a.cancel()
	}
	r.mu.Unlock()
	<-done
	return ctx.Err()
}

// Stop stops the runner like Shutdown, waiting at most 30 seconds for running jobs.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	if err := r.Shutdown(ctx); err != nil {
		r.log.Warn("job runner stopped with jobs still running", "err", err)
	}
}

// Pending returns the jobs that still need to run, in the order they were enqueued. Before Shutdown these are
// the queued jobs not started yet. After Shutdown they are the jobs that were never started, followed by the
// jobs whose context Shutdown canceled and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	var es []entry
	if r.closing {
		es = slices.Clone(r.notStart)
		canceled := slices.Clone(r.canceled)
		slices.SortFunc(canceled, func(a, b entry) int { return cmpSeq(a.seq, b.seq) })
		es = append(es, canceled...)
	} else {
		es = slices.Clone(r.waiting)
	}
	jobs := make([]Job, 0, len(es))
	for _, e := range es {
		jobs = append(jobs, e.job)
	}
	return jobs
}

func cmpSeq(a, b uint64) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	}
	return 0
}

