		if v := recover(); v != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", v, "stack", string(debug.Stack()))
			err = nil
		}
	}()
	return j.Run(ctx)
}

// removeWaiting drops the entry with sequence number seq from waiting. The caller holds mu.
func (r *Runner) removeWaiting(seq uint64) {
	for i, e := range r.waiting {
		if e.seq == seq {
			r.waiting = slices.Delete(r.waiting, i, i+1)
			return
		}
	}
}

