// and ErrStopped once Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closing {
		return ErrStopped
	}
	e := entry{seq: r.seq, job: j}
	select {
	case r.queue <- e:
	default:
		return ErrQueueFull
	}
	r.seq++
	r.waiting = append(r.waiting, e)
	return nil
}

