	} else {
		es = slices.Clone(r.waiting)
	}
	jobs := make([]Job, 0, len(es))
	for _, e := range es {
		jobs = append(jobs, e.job)
	}
	return jobs
}

func cmpSeq(a, b uint64) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	}
	return 0
}

