	subs := &subscriptions.Service{Store: st, Payments: pay, Clock: clk, Publisher: hooks}
	srv := api.New(st, api.Options{Clock: clk, Payments: pay, Subscriptions: subs, Webhooks: hooks, Mail: &mail.Outbox{Log: log}, Logger: log})

