	if got := r.Pending(); len(got) != 0 {
		t.Fatalf("pending = %v, want none", names(got))
	}
}

func TestSecondShutdownReturnsAtOnce(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan string, 1)
	if err := r.Enqueue(blockUntilCanceled("a", started)); err != nil {
		t.Fatal(err)
	}
	<-started
	first := make(chan error, 1)
	go func() { first <- r.Shutdown(context.Background()) }()
	time.Sleep(10 * time.Millisecond)

	second := make(chan error, 1)
	go func() { second <- r.Shutdown(context.Background()) }()
	select {
	case err := <-second:
		if err != nil {
			t.Fatalf("second Shutdown = %v, want nil", err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("second Shutdown blocked")
	}
	select {
	case <-first:
		t.Fatal("first Shutdown returned while a job was running")
	default:
	}
	// Let the first call finish.
	r.Stop()
	<-first
}

func TestStopAfterShutdownReturnsAtOnce(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	done := make(chan struct{})
	go func() { r.Stop(); close(done) }()
	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("Stop after Shutdown blocked")
	}
}

func TestStopWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	var finished atomic.Bool
	started := make(chan struct{}, 1)
	if err := r.Enqueue(Job{Name: "a", Run: func(context.Context) error {
		started <- struct{}{}
		time.Sleep(50 * time.Millisecond)
		finished.Store(true)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started
	r.Stop()
	if !finished.Load() {
		t.Fatal("Stop returned before the running job finished")
	}
}

func TestShutdownWithoutStartReturnsNil(t *testing.T) {
	r := NewRunner(2, 10, nil)
	if err := r.Enqueue(Job{Name: "a", Run: func(context.Context) error { t.Error("ran"); return nil }}); err != nil {
		t.Fatal(err)
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if got, want := names(r.Pending()), []string{"a"}; !slices.Equal(got, want) {
		t.Fatalf("pending = %v, want %v", got, want)
	}
}

func TestShutdownLeavesNoGoroutines(t *testing.T) {
	before := runtime.NumGoroutine()
	r := NewRunner(4, 10, nil)
	r.Start()
	started := make(chan string, 4)
	for _, name := range []string{"a", "b", "c", "d"} {
		if err := r.Enqueue(blockUntilCanceled(name, started)); err != nil {
			t.Fatal(err)
		}
	}
	for i := 0; i < 4; i++ {
		<-started
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	_ = r.Shutdown(ctx)

	deadline := time.Now().Add(2 * time.Second)
	for runtime.NumGoroutine() > before && time.Now().Before(deadline) {
		time.Sleep(time.Millisecond)
	}
	if n := runtime.NumGoroutine(); n > before {
		t.Fatalf("goroutines = %d, want at most %d", n, before)
	}
}
